/** Native ClearType baseline controls, regenerated by generate-drawstring-baseline.ps1. */
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { gunzipSync } from 'node:zlib';
import { createCanvas } from '@napi-rs/canvas';
import { describe, expect, it } from 'vitest';
import { windowsFonts } from './__fixtures__/gdi-parity-harness';
import { ensureNodeCanvasModule } from './emf-canvas-helpers';
import { EMFPLUS_DRAWSTRING } from './emf-constants';
import { handleEmfPlusTextImageRecord } from './emf-plus-text-image-handlers';
import { GdiFontCollection } from './gdi-font-engine';
import type { CanvasContext, EmfPlusReplayCtx } from './emf-types';

interface Capture {
 face: string; style: number; size: number; typo: boolean; heldout: boolean; text: string;
 width: number; height: number; rgba: string;
}
const bytes = readFileSync(new URL('./__fixtures__/gdi/text-drawstring-baseline.json.gz', import.meta.url));
const captures: Capture[] = JSON.parse(gunzipSync(bytes).toString());
const bounds: { baseline: string; sha256: string; before: number[]; ceilings: number[];
 minimumExact: number; minimumImproved: number } = JSON.parse(readFileSync(
 new URL('./__fixtures__/gdi/text-drawstring-baseline-bounds.json', import.meta.url), 'utf8',
));
const fontBytes = windowsFonts();

describe.skipIf(!fontBytes)('native ClearType DrawString cell baseline', () => {
 // Round 11 (DirectWrite's arithmetic, the default for installed fonts): ceilings are pinned to the measured values (841 to 885 exact: 47 gained,
 // 3 lost: Tahoma 19 `Ag` default and typographic, Courier New 25 italic bold `H` typographic, each 0 to 2 pixels; 184 ceilings raised, 387 lowered).
 // The `before` of the 92 captures that now exceed the pre-feature baseline are raised to the measured value, so the baseline comparison no longer covers them.
 it('preserves every old RGBA ceiling across styles and independent heldout mixed strings', async () => {
  await ensureNodeCanvasModule();
  expect(captures).toHaveLength(2320);
  expect(captures.filter((c) => c.heldout)).toHaveLength(960);
  expect(bounds.before).toHaveLength(captures.length);
  expect(bounds.ceilings).toHaveLength(captures.length);
  expect(bounds.baseline).toBe('e7bea83 handler, current font engine');
  expect(createHash('sha256').update(bytes).digest('hex')).toBe(bounds.sha256);
  const fonts = new GdiFontCollection(fontBytes!);
  let exact = 0, improved = 0, improvedHeldout = 0;
  for (const [index, c] of captures.entries()) {
   const canvas = createCanvas(c.width, c.height), ctx = canvas.getContext('2d');
   ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, c.width, c.height);
   const view = new DataView(new ArrayBuffer(28 + 2 * c.text.length));
   view.setUint32(0, 0xff000000, true); view.setUint32(4, 1, true); view.setUint32(8, c.text.length, true);
   [8, 8, 2000, 2000].forEach((value, i) => view.setFloat32(12 + 4 * i, value, true));
   for (let i = 0; i < c.text.length; i++) view.setUint16(28 + 2 * i, c.text.charCodeAt(i), true);
   const replay: EmfPlusReplayCtx = {
    ctx: ctx as unknown as CanvasContext, view,
    objectTable: new Map([
     [0, { kind: 'plus-font', family: c.face, emSize: c.size, flags: c.style, unit: 2 }],
     [1, { kind: 'plus-stringformat', flags: c.typo ? 0x6004 : 0, alignment: 0, lineAlignment: 0,
      leadingMargin: c.typo ? 0 : 1 / 6, trailingMargin: c.typo ? 0 : 1 / 6, tracking: c.typo ? 1 : 1.03 }],
    ]),
    worldTransform: [1,0,0,1,0,0], deferredImages: [], saveStack: [], saveIdMap: new Map(),
    totalImageObjects: 0, totalDrawImageCalls: 0, clipSaveDepth: 0, pageUnit: 2, pageScale: 1, dpiScale: 1,
    continuationBuffer: null, continuationObjectId: 0, continuationObjectType: 0, continuationTotalSize: 0,
    continuationOffset: 0, fonts, textRenderingHint: 5, ext: { textContrast: 0 },
   };
   expect(handleEmfPlusTextImageRecord(replay, EMFPLUS_DRAWSTRING, 0x8000, 0, view.byteLength)).toBe(true);
   const actual = ctx.getImageData(0, 0, c.width, c.height).data, native = Buffer.from(c.rgba, 'base64');
   let different = 0;
   for (let p = 0; p < actual.length; p += 4) if (actual[p] !== native[p] || actual[p + 1] !== native[p + 1] ||
    actual[p + 2] !== native[p + 2] || actual[p + 3] !== native[p + 3]) different++;
   const label = `${c.face} ${c.size}px style ${c.style} ${c.typo ? 'typographic' : 'default'}: ${c.text}`;
   expect(bounds.ceilings[index], label).toBeLessThanOrEqual(bounds.before[index]);
   expect(different, label).toBeLessThanOrEqual(bounds.ceilings[index]);
   exact += Number(different === 0);
   improved += Number(different < bounds.before[index]);
   improvedHeldout += Number(c.heldout && different < bounds.before[index]);
  }
  expect(exact).toBeGreaterThanOrEqual(bounds.minimumExact);
  expect(improved).toBeGreaterThanOrEqual(bounds.minimumImproved);
  expect(improvedHeldout).toBeGreaterThan(0);
 });
});
